export function verifyWhatsAppSignature(rawBody: Buffer, signature: string | undefined, appSecret: string): boolean {
  if (!rawBody || !signature || !appSecret) return false;
  if (!signature.startsWith('sha256=')) return false;
  const receivedHex = signature.slice('sha256='.length);
  if (!/^[0-9a-fA-F]+$/.test(receivedHex)) return false;
  const expected = createHmac('sha256', appSecret).update(rawBody).digest();
  const received = Buffer.from(receivedHex, 'hex');
  if (received.length !== expected.length) return false;
  return timingSafeEqual(received, expected);
}

// Multi-tenant: TODOS los canales del post deben aceptar la firma con SUS secretos.
export function verifyWhatsAppSignatureForChannels(rawBody: Buffer, signature: string | undefined, candidatesPerChannel: string[][]): boolean {
  if (candidatesPerChannel.length === 0) return false;
  return candidatesPerChannel.every((candidates) =>
    candidates.some((secret) => verifyWhatsAppSignature(rawBody, signature, secret)),
  );
}

export function encryptCredentials(payload: object): string {
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', loadKey(), iv);
  const ciphertext = Buffer.concat([
    cipher.update(Buffer.from(JSON.stringify(payload), 'utf8')),
    cipher.final(),
  ]);
  const envelope: CredentialsEnvelope = {
    v: 1,
    iv: iv.toString('base64'),
    authTag: cipher.getAuthTag().toString('base64'),
    ciphertext: ciphertext.toString('base64'),
  };
  return JSON.stringify(envelope);
}
